from builtins import range

try:
    from collections.abc import Mapping, Sequence
except ImportError:
    from collections import Mapping, Sequence
import logging
import os
import re
import six
import yaml
import datetime
from robot.libraries.BuiltIn import BuiltIn
from robot.libraries.DateTime import convert_time
from taf.managedobject import managedobject
from taf.collectors.core.factories.factory_registry import CollectorFactoryRegistry
from taf.collectors.core.entities.async_collectable import AsyncCollectableComponent
from taf.collectors.core.factories.collector_set_factory import CollectorSetFactory
try:
    from itertools import filterfalse
except ImportError:
    from itertools import ifilterfalse as filterfalse

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())

yaml.add_constructor(
    u"!timedelta",
    lambda loader, node: convert_time(loader.construct_scalar(node), "timedelta"),
    yaml.SafeLoader)
yaml.add_representer(
    datetime.timedelta,
    lambda dumper, data: dumper.represent_scalar(u'!timedelta', convert_time(data, "compact")))
yaml.add_constructor(
    u"!robot",
    lambda loader, node: BuiltIn().get_variable_value("${%s}" % loader.construct_scalar(node)),
    yaml.SafeLoader)


class CollectorKeywords(managedobject):
    """
    Examples of collector provided
    in `Collectors Example <https://confluence.int.net.nokia.com/display/CV/Collectors+Example>`_.
    """
    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'
    _namespace = "collectors"

    def load_configurations(self, *paths):
        r"""
        Load configurations for collectors and depending objects from one or more files.

        In the simplest case only the path of one YAML file, that contains all configurations, is passed.

        It is also possible to split up the YAML code into multiple files in order to share common parts
        in multiple contexts. The files specified by their paths can contain YAML code fragments.
        They are concatenated in the order of the paths.

        In case of references via YAML aliases and anchors, the order of the files must ensure,
        that anchors occur before aliases.

        The YAML code resulting from the concatenation of the file contents is loaded as a data structure of nested
        dictionaries and lists.

        Inside this data structure references to Robot variables (string values with the prefix "robot:") are resolved.

        :param list(str) paths: list of paths of files with YAML code (fragments)

        :return: configurations for collectors and depending objects
        :rtype: dict

        Usage example:

            .. code-block:: robotframework

                ${configurations}=  Load Configuration
                ...  credentials.yaml
                ...  executors.yaml
                ...  collectors.yaml
        """
        yaml_fragments = []
        for path in paths:
            with open(path) as file_obj:
                yaml_fragments.append(file_obj.read())
        yaml_string = "".join(yaml_fragments)
        return self._parse_yaml(yaml_string=yaml_string)

    def _parse_yaml(self, yaml_string):
        """
        Parse a YAML string and resolve Robot variables in it.

        :param str yaml_string: YAML string

        :return: configurations for collectors and depending objects
        :rtype: dict
        """
        configurations = yaml.safe_load(yaml_string)
        configurations = self._resolve(data=configurations)
        return configurations

    def parse_yaml(self, yaml_string):
        """
        Parse a YAML string and resolve Robot variables in it.

        :param str yaml_string: YAML string

        :return: configurations for collectors and depending objects
        :rtype: dict
        """
        return self._parse_yaml(yaml_string=yaml_string)

    def _resolve(self, data):  # noqa: C901
        """
        Resolve references to Robot variables.

        :param object data: data structure in configurations for collectors and depending objects

        :return: data structure with resolved references to Robot variables
        :rtype: object
        """
        if isinstance(data, Mapping):
            for key in data:
                data[key] = self._resolve(data[key])
        elif isinstance(data, Sequence):
            if not isinstance(data, six.string_types):
                for i in range(len(data)):
                    data[i] = self._resolve(data[i])
            else:
                match = re.match(r"robot:(.*)", data)
                if match:
                    return BuiltIn().get_variable_value("${%s}" % match.group(1))
        return data

    def create_collectors(self, configurations, names=None):
        r"""
        Create collectors for given collector configurations.

        :param list(dict) configurations: list of collector configurations
        :param str names:
            comma separated list of collector names (default is None: create all collectors in configurations)

        Usage example:

            .. code-block:: robotframework


                ${configurations}=  Load Configurations
                ...  /tmp/collectors.yaml
                Create Collectors
                ... names=gnb_oam_journal,gnb_oam_tcpdump
                ... configurations=${configurations['collectors']}

                ${oam}=  Create Dictionary
                ...  host=192.168.125.10
                ...  user=robot
                ...  password=rastre1
                ${gnb_oam_tcpdump}=  Create Dictionary
                ...  name=gnb_oam_tcpdump
                ...  type=tcpdump
                ...  executor=${oam}
                ${configurations}=  Create List
                ...  ${gnb_oam_tcpdump}
                Create Collectors
                ...  configurations=${configurations}

                ${yaml}=  Catenate  SEPARATOR=\n  # prepend \u200b before YAML spaces to keep Robot from collapsing them
                ...  credentials:
                ...    - &test_credentials
                ...      user: "robot:vnf_config['parameters']['extra_cloud_config_data']\\
                ...        ['users'][1]['name']"
                ...      password: "robot:vnf_config['parameters']['extra_cloud_config_data']\\
                ...        ['users'][1]['plain_text_passwd']"
                ...  executors:
                ...    - &oam
                ...      host: robot:tl.gnbs[0].cu.oam_ssh_connection_details.host
                ...      <<: *test_credentials
                ...    - &cpif
                ...      host: cpif-0.local
                ...      <<: *test_credentials
                ...      proxy: *oam
                ...  collectors:
                ...    - &gnb_cpif_tcpdump
                ...      name: gnb_cpif_tcpdump
                ...      type: tcpdump
                ...      executor: *cpif
                ...    - &gnb_cpif_journal
                ...      name: gnb_cpif_journal
                ...      type: journal
                ...      executor: *cpif
                ...    - &bb3
                ...      name: bb3
                ...      type: group
                ...      members:
                ...      - *gnb_cpif_tcpdump
                ...      - *gnb_cpif_journal
                ${yaml}=  Replace String  ${yaml}  \u200b  ${EMPTY}
                ${configuration}=  Parse YAML  ${yaml}
                Create Collectors
                ...  configurations=${configuration['collectors']}

        """

        if names is not None:
            configurations = [configuration for configuration in configurations
                              if configuration["name"] in names.split(",")]
        self._create_collectors_and_add_in_alias(configurations=configurations)

    def _create_collectors_and_add_in_alias(self, configurations):
        """
        Creates and add collectors for the given collector configurations.

        :param dict configurations: collector configurations
        """
        logging.debug("creating collectors for configurations %r", configurations)
        collectors = CollectorSetFactory(
            available_collectors=self._get_all_alias_from_collector_namespace()).create(
            configuration=configurations,
            existing_arguments={})
        for name, collector in collectors.items():
            self.set_alias(name, collector)

    def _get_all_alias_from_collector_namespace(self):
        robot_variables = self._builtin.get_variables()
        collectors = {}
        for variable_name in robot_variables:
            if "${collectors::" in variable_name:
                collectors[variable_name.replace("${collectors::", '').replace("}", '')] = robot_variables[
                    variable_name]
        return collectors

    def start_collectors(self, names):
        """
        Start collectors for given list of collector names.

        :param str names: comma separated name list of startable collectors
        """
        for name in names.split(','):
            collector = self.get_alias_value(name)
            collector.start()

    def stop_collectors(self, names):
        """
        Stop collectors for given list of collector names.

        :param str names: comma separated name list of stoppable collectors
         """
        for name in names.split(','):
            collector = self.get_alias_value(name)
            collector.stop()

    def _get_target_dir(self, target_dir=None):
        if target_dir is None:
            target_dir = os.path.join(
                self._builtin.get_variable_value("${OUTPUT DIR}"),
                self._builtin.get_variable_value("${SUITE NAME}"),
                self._builtin.get_variable_value("${TEST NAME}"))
        return target_dir

    def collect_collectors(self, names, target_dir=None):
        """
        Collect generated files for given list of collector names.

        :param str names: comma separated name list of collectors
        :param str target_dir:
            local storage path for collected files
            (default: ${OUTPUTDIR}/${SUITENAME}/${TESTNAME})
        """
        target_dir = self._get_target_dir(target_dir=target_dir)
        for name in names.split(','):
            collector = self.get_alias_value(name)
            collector.collect(target_dir=target_dir)

    def async_collect_collectors(self, names, target_dir=None):
        """
        Asynchronously collect generated files for given list of collector names.

        Collectors and CollectorGroups in "names" must be asynchronous.

        :param str names: comma separated name list of collectors
        :param str target_dir:
            local storage path for collected files
            (default: ${OUTPUTDIR}/${SUITENAME}/${TESTNAME})
        """
        target_dir = self._get_target_dir(target_dir=target_dir)
        awaitables = []
        for name in names.split(','):
            collector = self.get_alias_value(name)
            awaitables.extend(collector.async_collect(target_dir=target_dir))
        return awaitables

    @staticmethod
    def wait_for_operations(awaitables):
        """
        Asynchronously wait for file generation started by async_collect() to finish.
        """
        AsyncCollectableComponent.wait(awaitables)

    def create_command_collector(
            self,
            name,
            find_command,
            executor=None,
            map_command=None,
            postprocess_command=None,
            cleanup_command=None,
            start_command=None,
            stop_command=None):
        """
        Create a collector with configurable commands.

        :param str name: alias for the collector
        :param str find_command:
            command to be executed on the remote host to prepare files for transfer
            (must print one line on stdout for each remote file path to be transferred)
        :param str map_command:
            command to be executed on the local host to map remote file paths to local file paths
            relative to subdirectory of this collector under the target_dir given to collect_collectors
            (must read remote paths one per line on stdin and write mapped local paths one per line on stdout,
            default mapping: relative local path = basename of remote path)
        :param str postprocess_command:
            command to be executed on the local host in the subdirectory of this collector under the
            target_dir given to collect_collectors after files have been transfered
        :param str cleanup_command:
            command to be executed on the remote host to cleanup temporary files after the transfer
        :param str start_command:
            command to be executed on the remote host to start the collector, if it is startable
        :param str stop_command:
            command to be executed on the remote host to stop the collector, if it is stoppable
        :param dict executor: executor configuration, default: local executor
        """
        configuration = {'type': "command", 'name': name, 'find_command': find_command}
        for parameter_name in (
                "map_command", "postprocess_command", "cleanup_command",
                "start_command", "stop_command", "executor"):
            parameter_value = eval(parameter_name)
            if parameter_value is not None:
                configuration[parameter_name] = parameter_value
        collector_factory = CollectorFactoryRegistry.get_instance()[configuration["type"]]()
        collector = collector_factory.create(
            configuration=configuration,
            existing_arguments={})
        self.set_alias(name, collector)

    def create_collector_group(self, name, members):
        """
        Create collector group.

        :param str name: name of the collector group
        :param str members: comma separated name list of members of the group (collectors or collector groups)
        """
        configuration = {'type': "group", 'name': name}
        members_list = members.split(",")
        missing_aliases = list(filterfalse(self.get_alias_value, members_list))
        if missing_aliases:
            raise RuntimeError(
                "Aliases not found for members: {missing_aliases}".format(
                    missing_aliases=', '.join(sorted(missing_aliases))))
        existing_arguments = {'members': list(map(self.get_alias_value, members_list))}

        collector_factory = CollectorFactoryRegistry.get_instance()[configuration["type"]]()
        collector_group = collector_factory.create(
            configuration=configuration,
            existing_arguments=existing_arguments)
        self.set_alias(name, collector_group)

    def setup_collectors(self, names, group=None):
        for name in names.split(','):
            collector = self.get_alias_value(name)
            collector.setup(group=group)

    def teardown_collectors(self, names, group=None, force=False):
        for name in names.split(','):
            collector = self.get_alias_value(name)
            collector.teardown(group=group, force=force)
